compare.check:
(args, got) => {
      const { ops, args: a } = args;
      if (!Array.isArray(got) || got.length !== ops.length || got[0] !== null) return false;
      const orig = a[0][0], n = orig.length, sorted = JSON.stringify([...orig].sort((x, y) => x - y));
      const shuffles = [];
      for (let i = 1; i < ops.length; i++) {
        const g = got[i];
        if (!Array.isArray(g) || g.length !== n) return false;
        if (ops[i] === "reset") { if (JSON.stringify(g) !== JSON.stringify(orig)) return false; }
        else if (ops[i] === "shuffle") {
          if (JSON.stringify([...g].sort((x, y) => x - y)) !== sorted) return false;
          shuffles.push(g);
        } else return false;
      }
      const N = shuffles.length;
      if (N < 600 || n < 2) return true;
      // each value at each position: expected 1/n
      if (n <= 6) {
        for (let pos = 0; pos < n; pos++) for (const v of orig) {
          const f = shuffles.filter(s => s[pos] === v).length / N;
          if (Math.abs(f - 1 / n) > 0.08) return false;
        }
      }
      // each whole ordering: expected 1/n!
      if (n <= 3) {
        const freq = new Map();
        for (const s of shuffles) { const k = s.join(","); freq.set(k, (freq.get(k) || 0) + 1); }
        const perms = n === 2 ? 2 : 6;
        if (freq.size !== perms) return false;
        for (const c of freq.values()) if (Math.abs(c / N - 1 / perms) > 0.06) return false;
      }
      return true;
    }
